package com.axelsarassamit.ridedeck.dash;
import android.app.*;import android.os.*;import android.net.Uri;import android.content.*;import android.provider.MediaStore;import android.widget.*;import android.view.WindowManager;import java.io.*;import java.util.*;
import androidx.media3.common.*;import androidx.media3.transformer.*;import androidx.media3.effect.*;
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public final class OverlayExportActivity extends Activity {
 Transformer transformer;File output;TextView progress;boolean completed;final Handler handler=new Handler(Looper.getMainLooper());
 public void onCreate(Bundle state){super.onCreate(state);LinearLayout page=DashUi.page(this);setContentView(page);DashUi.text(this,page,"Export with overlays",28);progress=DashUi.text(this,page,"Preparing your video copy",18);DashUi.text(this,page,"Keep Dash open until export finishes. Your original recording is preserved. Rotating or leaving this screen cancels the export.",16);DashUi.button(this,page,"Cancel",v->finish());getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
  try{if(RecordingService.running||RecordingService.finalizing)throw new IOException("Stop recording before exporting overlays");if(Build.VERSION.SDK_INT<29)throw new IOException("Overlay gallery export requires Android 10 or newer");File clip=new File(getIntent().getStringExtra("clip"));if(!clip.getCanonicalPath().startsWith(new ClipStore(this).root().getCanonicalPath()+File.separator)||!ClipStore.finalized(clip))throw new IOException("Finalized clip unavailable");if(getCacheDir().getUsableSpace()<clip.length()*3+512L*1024*1024)throw new IOException("Not enough free space for an overlay copy");
   output=new File(getCacheDir(),"overlay-"+System.currentTimeMillis()+".mp4");RideTelemetry telemetry=new RideTelemetry(clip);DashSettings settings=new DashSettings(this,true);
   transformer=new Transformer.Builder(this).setVideoMimeType(MimeTypes.VIDEO_H264).addListener(new Transformer.Listener(){
    @Override public void onCompleted(Composition composition,ExportResult result){completed=true;progress.setText("Saving to gallery");save(clip);}
    @Override public void onError(Composition composition,ExportResult result,ExportException error){handler.removeCallbacks(tick);progress.setText("Export failed: "+error.getMessage());if(output!=null)output.delete();}
   }).build();
   EditedMediaItem item=new EditedMediaItem.Builder(MediaItem.fromUri(Uri.fromFile(clip))).setEffects(new Effects(Collections.emptyList(),Collections.singletonList(new OverlayEffect(Collections.singletonList(new TelemetryOverlay(telemetry,settings)))))).build();transformer.start(item,output.getPath());handler.post(tick);
  }catch(Exception e){progress.setText(e.getMessage());}
 }
 final Runnable tick=new Runnable(){public void run(){if(transformer==null||completed||isDestroyed())return;ProgressHolder holder=new ProgressHolder();if(transformer.getProgress(holder)==Transformer.PROGRESS_STATE_AVAILABLE)progress.setText("Creating overlay video · "+holder.progress+"%");handler.postDelayed(this,500);}};
 void save(File clip){new Thread(()->{Uri uri=null;try{ContentValues values=new ContentValues();values.put(MediaStore.Video.Media.DISPLAY_NAME,"Dash-"+clip.getParentFile().getName()+"-"+clip.getName().replace(".mp4","-overlay.mp4"));values.put(MediaStore.Video.Media.MIME_TYPE,"video/mp4");values.put(MediaStore.Video.Media.RELATIVE_PATH,"Movies/RideDeckDash");values.put(MediaStore.Video.Media.IS_PENDING,1);uri=getContentResolver().insert(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new IOException("Gallery unavailable");try(InputStream in=new FileInputStream(output);OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("Gallery unavailable");byte[] data=new byte[65536];int n;while((n=in.read(data))!=-1)out.write(data,0,n);}values.clear();values.put(MediaStore.Video.Media.IS_PENDING,0);getContentResolver().update(uri,values,null,null);runOnUiThread(()->{progress.setText("Saved in Movies / RideDeckDash");Toast.makeText(this,"Overlay video saved",Toast.LENGTH_LONG).show();});}catch(Exception error){if(uri!=null)getContentResolver().delete(uri,null,null);runOnUiThread(()->progress.setText("Gallery export failed"));}finally{if(output!=null)output.delete();}},"DashOverlayGallery").start();}
 protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(transformer!=null&&!completed)transformer.cancel();if(output!=null&&!completed)output.delete();super.onDestroy();}
}
